                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and (nr, nc) not in seen):
                    seen.add((nr, nc))
                    stack.append((nr, nc))

    # Remaining zeros are enclosed pockets.
